		this.identity		= identity;
		this.projector 		= new ImagingOrderEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ImagingOrderRepository.class) );
		this.validator		= applicationContext.getBean(ImagingOrderValidator.class) ;
